<?php
use Illuminate\Contracts\Console\Kernel;
use Illuminate\Support\Facades\DB;
use Plugins\Yutiv\LiveCommerce\Enums\LiveEntity as E;
use Plugins\Yutiv\LiveCommerce\Models\LiveTenant;
use Plugins\Yutiv\LiveCommerce\Contracts\LiveRepositoryInterface;
use Plugins\Yutiv\LiveCommerce\Services\LiveFinanceReportService;

$root=dirname(__DIR__,5);require $root.'/vendor/autoload.php';$app=require $root.'/bootstrap/app.php';$app->make(Kernel::class)->bootstrap();
if(!str_contains(str_replace('\\','/',base_path()),'/live-accounting060-browser'))throw new RuntimeException('isolated checkout required');
$db=DB::connection();foreach([$db->getPdo(),$db->getReadPdo()] as $pdo){$scope=$pdo->query('SELECT DATABASE() db,@@port port')->fetch(PDO::FETCH_ASSOC);if($scope['db']!=='live_accounting060_isolated_browser'||(int)$scope['port']!==33319)throw new RuntimeException('isolated DB required');}
$tenant=LiveTenant::where('slug','golfif')->firstOrFail();$repo=app(LiveRepositoryInterface::class);$service=app(LiveFinanceReportService::class);$date=now($tenant->timezone)->format('Y-m-d');
if(($argv[1]??'')==='seed'&&!$repo->query(E::Expense,$tenant->id)->where('source_key','performance-060-0')->exists()){
    $category=$repo->query(E::ExpenseCategory,$tenant->id)->where('code','salary')->firstOrFail();
    for($start=0;$start<10000;$start+=200){$rows=[];for($n=$start;$n<$start+200;$n++)$rows[]=['tenant_id'=>$tenant->id,'category_id'=>$category->id,'category_code'=>'salary','category_name'=>'합성 성능 인건비','cost_group'=>'fixed','treatment'=>'operating','occurred_on'=>$date,'currency'=>'KRW','amount_original'=>'1000.00','exchange_rate'=>'1.000000','amount_krw'=>1000,'rate_date'=>$date,'rate_source'=>'synthetic load only','source_kind'=>'manual','source_key'=>'performance-060-'.$n,'status'=>'posted','actor_id'=>0,'memo'=>'격리 합성 읽기 부하','created_at'=>now(),'updated_at'=>now()];$repo->query(E::Expense,$tenant->id)->insert($rows);}
}
$counts=[];foreach([E::Product,E::Option,E::Unit,E::Movement,E::Order,E::OrderLine,E::Expense,E::FundEntry,E::Report,E::ReportRow] as $entity)$counts[$entity->name]=$repo->query($entity,$tenant->id)->count();
$queryCount=0;$db->disableQueryLog();$db->listen(function($event)use(&$queryCount){$queryCount++;});$runs=[];foreach(['day','week','month'] as $period){$from=match($period){'week'=>now($tenant->timezone)->startOfWeek(1)->format('Y-m-d'),'month'=>now($tenant->timezone)->startOfMonth()->format('Y-m-d'),default=>$date};$queryCount=0;memory_reset_peak_usage();$start=hrtime(true);$r=$service->report($tenant->id,0,$from,$date,$period);$runs[]=['operation'=>'report','period'=>$period,'from'=>$from,'to'=>$date,'milliseconds'=>round((hrtime(true)-$start)/1e6,3),'peak_mib'=>round(memory_get_peak_usage(true)/1048576,2),'queries'=>$queryCount,'fixed_krw'=>$r['totals']['fixed'],'source_flags'=>$r['flags']];$db->disableQueryLog();}
$queryCount=0;memory_reset_peak_usage();$start=hrtime(true);$uuid=$service->saveOnce($tenant->id,0,['operation_key'=>'performance-'.bin2hex(random_bytes(8)),'from'=>$date,'to'=>$date,'period'=>'day']);$saved=$service->saved($tenant->id,0,$uuid);$runs[]=['operation'=>'save-report','milliseconds'=>round((hrtime(true)-$start)/1e6,3),'peak_mib'=>round(memory_get_peak_usage(true)/1048576,2),'queries'=>$queryCount,'uuid'=>$uuid,'detail_rows'=>$saved['report']->row_count,'parts'=>$saved['parts'],'fixed_krw'=>$saved['report']->result['totals']['fixed']];$db->disableQueryLog();
foreach([1,501] as $number){$queryCount=0;memory_reset_peak_usage();$start=hrtime(true);$page=$repo->query(E::Expense,$tenant->id)->where('occurred_on',$date)->orderByDesc('id')->paginate(20,['*'],'page',$number);$runs[]=['operation'=>'expense-page','page'=>$number,'total'=>$page->total(),'rows'=>$page->count(),'milliseconds'=>round((hrtime(true)-$start)/1e6,3),'peak_mib'=>round(memory_get_peak_usage(true)/1048576,2),'queries'=>$queryCount];}
$pageSums=0;$pageCount=0;$expenseQuery=$repo->query(E::Expense,$tenant->id)->where('occurred_on',$date)->where('cost_group','fixed')->where('source_kind','!=','reversal');do{$page=$expenseQuery->clone()->orderBy('id')->forPage(++$pageCount,100)->get();$pageSums+=(int)$page->sum('amount_krw');}while($page->count()===100);if($pageSums!==$saved['report']->result['totals']['fixed'])throw new RuntimeException('page sum mismatch');
$result=['php'=>PHP_VERSION,'mysql'=>$db->selectOne('SELECT VERSION() v')->v,'port'=>33319,'timezone'=>$tenant->timezone,'counts'=>$counts,'runs'=>$runs,'expense_page_sum_krw'=>$pageSums,'expense_pages'=>$pageCount];file_put_contents(base_path('accounting060-evidence/performance.json'),json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));echo json_encode($result,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR);
